package vn.eventplatform.ad.domain;
import jakarta.persistence.*; import lombok.*; import vn.eventplatform.ad.enums.BannerPosition; import java.time.LocalDateTime;
@Entity @Table(name="banners") @Getter @Setter @NoArgsConstructor public class Banner extends BaseEntity { @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="campaign_id",nullable=false) private AdCampaign campaign; @Column(name="image_url",nullable=false) private String imageUrl; @Column(name="pending_image_url") private String pendingImageUrl; @Enumerated(EnumType.STRING) @Column(nullable=false) private BannerPosition position; @Column(nullable=false) private Integer priority=0; @Column(name="starts_at",nullable=false) private LocalDateTime startsAt; @Column(name="ends_at",nullable=false) private LocalDateTime endsAt; @Column(nullable=false) private Boolean active=true; }
